import { isCutout } from "@/lib/products";

// Widths generated by scripts/optimize-images.mjs for photos.
export const PHOTO_WIDTHS = [480, 800, 1200, 1600];
export const srcSet = (slug: string, widths = PHOTO_WIDTHS) =>
  widths.map((w) => `/img/${slug}-${w}.webp ${w}w`).join(", ");

type Props = {
  slug: string;
  alt: string;
  sizes: string;
  className?: string;
  /** Above-the-fold image that is likely the LCP: loads first. */
  priority?: boolean;
  eager?: boolean;
};

// Responsive <img> for the pre-generated WebP files in /public/img.
// Cheese cut-outs are square (200-900); the rest are photos (480-1600).
export function ProductImage({ slug, alt, sizes, className, priority, eager }: Props) {
  const cutout = isCutout(slug);
  const widths = cutout ? [200, 480, 640, 900] : PHOTO_WIDTHS;
  return (
    <img
      src={`/img/${slug}-${cutout ? 480 : 800}.webp`}
      srcSet={srcSet(slug, widths)}
      sizes={sizes}
      alt={alt}
      // Cut-outs are square, so their box is known before they load.
      {...(cutout ? { width: 480, height: 480 } : {})}
      className={className}
      loading={priority || eager ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : undefined}
      decoding="async"
    />
  );
}
